&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Kadın Kolları Başkanımız Nurg&amp;uuml;l Beytiye Ekinci&amp;rsquo;nin basın a&amp;ccedil;ıklaması metnidir;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Değerli basın mensupları, kıymetli hanımefendiler, beyefendiler, sevgili kız kardeşlerimiz;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bug&amp;uuml;n 25 Kasım Kadına Y&amp;ouml;nelik Şiddete Karşı Uluslararası M&amp;uuml;cadele G&amp;uuml;n&amp;uuml;.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;1960 yılında Dominik Cumhuriyeti&amp;rsquo;nde Mirabal Kardeşlerin diktat&amp;ouml;rl&amp;uuml;ğe karşı duruşlarından &amp;ouml;t&amp;uuml;r&amp;uuml; katledilmelerinin anısına ilan edilen bug&amp;uuml;n; ne yazık ki kadına karşı şiddeti sonlandırmadı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bug&amp;uuml;n kadınlara karşı y&amp;ouml;neltilen en b&amp;uuml;y&amp;uuml;k şiddet ş&amp;uuml;phesiz ki savaştır. D&amp;uuml;nyanın neresinde olursa olsun, &amp;ccedil;ıkan her savaşın bedeli ne yazık ki kadınlar ve &amp;ccedil;ocuklar tarafından &amp;ouml;denmektedir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İsrail&amp;rsquo;in Gazze&amp;rsquo;de uyguladığı soykırımda, Bug&amp;uuml;n Somali&amp;rsquo;de devam eden i&amp;ccedil; savaşta, zul&amp;uuml;m altında olan Doğu T&amp;uuml;rkistan&amp;rsquo;da, yıllardır her t&amp;uuml;rl&amp;uuml; acıyla sınanan Yemen&amp;rsquo;de ve Afrika kara par&amp;ccedil;asında kadınlar ağır bedeller &amp;ouml;demektedir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Gazze&amp;rsquo;de &amp;ccedil;ocukların annesiz, annelerin yavrusuz kaldığını g&amp;ouml;rd&amp;uuml;k. Yavrusunun &amp;ouml;l&amp;uuml; bedenine sarılan anneler g&amp;ouml;rd&amp;uuml;k. A&amp;ccedil; bırakılan, hastalığa terk edilen anneler ve kadınlar g&amp;ouml;rd&amp;uuml;k.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Gazze&amp;rsquo;de lise bitirme sınavında %96,7 ortalamayla b&amp;uuml;y&amp;uuml;k bir başarı kazanan gen&amp;ccedil; kızımız Şehide Duha Nazmi Ebu Dellal&amp;rsquo;ın, sevincini yaşayacak bir g&amp;uuml;n&amp;uuml; bile olmadan annesi ve altı kardeşiyle birlikte katledilişine şahit olduk.&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Hind Receb&amp;rsquo;in &amp;ouml;ld&amp;uuml;r&amp;uuml;ld&amp;uuml;ğ&amp;uuml; b&amp;ouml;lgenin birka&amp;ccedil; metre &amp;ouml;tesinde, yardım &amp;ccedil;ağrıları g&amp;uuml;nlerce duyulmayan &amp;ouml;ğretmen Ghada Rabah&amp;rsquo;ın evi ikinci kez bombalanarak ailesiyle birlikte enkaz altında yok edildi. Sivil savunma ekipleri ulaştığında ise geriye sadece sessizlik kalmıştı.&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Kud&amp;uuml;s Tugayları S&amp;ouml;zc&amp;uuml;s&amp;uuml; Ebu Hamza&amp;rsquo;nın eşi Şeyma Ebu Seyf&amp;rsquo;in, hi&amp;ccedil;bir g&amp;uuml;venli alan bırakılmayan Gazze&amp;rsquo;de hedef alınarak yaşamdan koparıldığını g&amp;ouml;rd&amp;uuml;k.&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Fakat ne acıdır ki bu tablo karşısında kadına karşı şiddet, &amp;ccedil;ocuk hakları, &amp;ouml;zg&amp;uuml;rl&amp;uuml;k ve demokrasi gibi s&amp;ouml;ylemlerde başı &amp;ccedil;eken Batı devletlerinden tek bir tepki, tek bir somut adım g&amp;ouml;rmedik.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Kardeşlerimiz katledilirken Batıda kadın hakları dersleri veren, &amp;ouml;zg&amp;uuml;rl&amp;uuml;k ve insan haklarından bahseden ikiy&amp;uuml;zl&amp;uuml; tutumu unutmayacağız.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Değerli basın mensupları; d&amp;uuml;nyada veya T&amp;uuml;rkiye&amp;rsquo;de, nerede olursa olsun kadınlara y&amp;ouml;nelik şiddet, insanlığın ortak utancıdır ve bu utanca karşı sessizlik, su&amp;ccedil;a ortak olmaktır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bizler yıllardır &amp;uuml;lkemizde de kadın hakları i&amp;ccedil;in &amp;ccedil;alışıyor, şiddete karşı m&amp;uuml;cadele ediyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Ccedil;&amp;uuml;nk&amp;uuml; &amp;uuml;lkemizde &amp;ouml;zellikle son yıllarda kadına karşı şiddet had safhaya ulaşmış durumdadır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Sadece bu yıl, geride kalan 11 ayda 400&amp;rsquo;&amp;uuml;n &amp;uuml;zerinde kardeşimiz cinayete kurban gitti. T&amp;uuml;rkiye&amp;rsquo;de her g&amp;uuml;n en az bir kadın canice katlediliyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Kocaeli&amp;rsquo;ndeki yangın fabrikasında, k&amp;ouml;t&amp;uuml; &amp;ccedil;alışma koşullarının kurbanı olan Şeng&amp;uuml;l Yılmaz (59), Hanım G&amp;uuml;lek (52), Esma Dikan (31), Tuğba Taşdemir (17), Nisanur Taşdemir (15) ve Cansu Esteoğlu (15) gibi emek&amp;ccedil;i kadınlarımızı kaybettik.&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Sadece iki aylık evliyken, mesleğine aşkla bağlı gen&amp;ccedil; bir hemşire olan Sevcan Demir&amp;rsquo;in eşi tarafından satırla vahşice katledilmesine tanık olduk. Onun sessiz &amp;ccedil;ığlığı h&amp;acirc;l&amp;acirc; kulaklarımızdadır.&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Televizyonlarda, s&amp;ouml;zde m&amp;uuml;ziklerde, sosyal medya i&amp;ccedil;eriklerinde, dizilerde, sabah kuşaklarında kadına şiddeti &amp;ouml;zendiren, kadını bir meta gibi sunan bir anlayışa son verilmediği, cezalar caydırıcı olmadığı s&amp;uuml;rece T&amp;uuml;rkiye&amp;rsquo;de kadına y&amp;ouml;nelik şiddet hi&amp;ccedil;bir zaman bitmeyecektir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Kadından yana gibi g&amp;ouml;r&amp;uuml;n&amp;uuml;p annelik mertebesini aşağılayan, kadına hedonizmi tek &amp;ccedil;ıkar yol olarak dayatan, kadını &amp;ouml;verken aslında kadına en b&amp;uuml;y&amp;uuml;k k&amp;ouml;t&amp;uuml;l&amp;uuml;ğ&amp;uuml; yapan sapkın fikir ve akımların da kadına karşı bir şiddet olduğu apa&amp;ccedil;ık ortadadır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bilinmelidir ki bizim ne y&amp;uuml;ce dinimiz İslam&amp;rsquo;da, ne geleneğimizde ne de &amp;ouml;rf&amp;uuml;m&amp;uuml;zde kadına şiddet yoktur.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;S&amp;ouml;z konusu şiddet sadece fiziki şiddet değildir. Bug&amp;uuml;n iş yerinde mobinge uğrayan,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İşten atılırım korkusuyla hamile kalmaktan &amp;ccedil;ekinen,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Doğumdan sonra evladıyla ilgilenemeden işe d&amp;ouml;nmek zorunda kalan,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Sosyal medyada fotoğrafları ifşa edilerek dijital şiddete maruz kalan,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Enflasyon ve ağır yaşam maliyetlerinden dolayı &amp;ccedil;ocuğunun karşısında boynunu b&amp;uuml;ken kadınların da şiddet mağduru olduğunu biliyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Kadını sadece ucuz iş g&amp;uuml;c&amp;uuml; olarak g&amp;ouml;ren, aile kurumunu g&amp;ouml;rmezden gelen anlayış bu şiddete son veremez.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bizler artık kadın haklarının s&amp;ouml;zde değil, &amp;ouml;zde olmasını talep ediyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Artık hamasi c&amp;uuml;mleler değil, kadın hakları ve kadına karşı şiddet konusunda somut adımlar atılmasını istiyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

